/// <summary>
/// METCoverNoteDP class.
/// </summary>
[SrsReportParameterAttribute(classStr(METOrderShipmentBundlingReportContract)),
 SRSReportQueryAttribute(queryStr(METOrderShipmentBundlingReportingJobQuery))]
public class METSalesOrderShipmentBundlingReportDP extends SrsReportDataProviderPreProcessTempDB //PreProcessTempDB
{
    METOrderShipmentBundlingReportContract      contract;
    METOrderShipmentBundlingReportHeaderTmp     bundleHeaderTmp;
    METCommonReportContract                     commonReportContract;
    METCoverNoteContract                        coverNoteContract;
    METDeliveryNoteReportContract               deliveryNoteContract;
    METCommonContinuingPermissionNoticeContract continuePermissionNoticeContract;
    METCoverNoteDP                              coverNoteDP;
    METCCRDP                                    ccrDP;
    METPickupAdviceReportDP                     pickupAdviceReportDP;
    METPickupAdviceReportContract               pickupAdviceReportContract;
    METSalesDangerousGoodsManifestDP            metSalesDangerousGoodsManifestDP;
    METSalesMultimodalDangerousGoodsDP          salesMultimodalDangerousGoodsDP;
    METSOContinuingPermissionNoticeDP           soContinuingPermissionNoticeDP;
    METDeliveryNoteReportDP                     deliveryNoteReportDP;
    MetShipmentId                               shipmentId;
    MetLoadId                                   loadId;
    boolean                                     isReprint;

    METBundleSalesCTInvoiceTmp                  bundleSalesCTInvoiceTmp;
    METBundleSalesInvoiceHeaderFooterTmp        bundleSalesInvoiceHeaderFooterTmp;
    METBundleSalesInvoiceLocalizationTmp        bundleSalesInvoiceLocalizationTmp;
    METBundleSalesInvoiceTmp                    bundleSalesInvoiceTmp;
    METBundleSysDocuBrandDetailsRegularTmp      bundleSysDocuBrandDetailsRegularTmp;
    METBundleSalesInvoicePaymentStubTmp         bundleSalesInvoicePaymentStubTmp;

    METBundleGuid         bundleHeaderReportGuid;
    METBundleGuid         headerTableGuid;


}

