/// <summary>
/// ProcessReport
/// </summary>
public void processReport()
{
    METSalesOrderShipmentLoadHeader     shipmentLoadHeader, shipmentLoadHeaderCount;
    METSalesOrderShipmentLoadLines      shipmentLoadLines;
    Str1260                             listOfShipmentsInLoad;
    METFinalizationDocument             finalisationDocument;
    CustTable                           custTable;
    METProcMetrics                      procMetrics = METProcMetricsScope::current();

    boolean                             isdeliveryNotePrinted, isInvoicePrinted;

    bundleHeaderReportGuid = guid2Str(newGuid());
    contract = this.parmDataContract();

    shipmentId  = contract.parmShipmentId();
    loadId      = contract.parmLoadId();
    isReprint     = contract.parmIsReprint();

    try
    {
        if (!isReprint)
        {
            select count(RecId) from shipmentLoadHeaderCount
                where shipmentLoadHeaderCount.LoadId == loadId;
        }

        while select ShipmentId from shipmentLoadHeader
            group by ShipmentId
            where shipmentLoadHeader.LoadId == loadId
        {
            if (listOfShipmentsInLoad)
            {
                listOfShipmentsInLoad += ', ';
            }
            listOfShipmentsInLoad += shipmentLoadHeader.ShipmentId;
        }

        select firstonly shipmentLoadHeader
            where shipmentLoadHeader.ShipmentId == shipmentId   &&
                shipmentLoadHeader.LoadId == loadId;

        container  isReportPrinted = shipmentLoadHeader.DocumentPrintedCon;

        custTable = CustTable::find(shipmentLoadHeader.CustAccount);
        METCustTable metCustTable = METCustTable::find(shipmentLoadHeader.CustAccount);

        finalisationDocument = metCustTable.FinalizationDocument;

        bundleHeaderTmp.FinalizationDocument = finalisationDocument;
        bundleHeaderTmp.EInvoice = metCustTable.EmailSalesInvoice;//BUG285816
        bundleHeaderTmp.CustName = custTable.name();
        bundleHeaderTmp.Warehouse = shipmentLoadHeader.Warehouse;
        bundleHeaderTmp.LoadID = loadId;
        bundleHeaderTmp.ShipmentID = shipmentId;
        bundleHeaderTmp.Route = shipmentLoadHeader.Route;
        bundleHeaderTmp.RouteStopNum = shipmentLoadHeader.RouteStopNum;
        bundleHeaderTmp.ListOfShipmentsInLoad = listOfShipmentsInLoad;
        bundleHeaderTmp.CustomerInvoiceToEmail = this.getCustomerInvoiceEmailIds(shipmentLoadHeader.CustAccount);

        if (isReprint)
        {
            bundleHeaderTmp.TotalNumOfShipment = 1;
        }
        else
        {
            bundleHeaderTmp.TotalNumOfShipment = shipmentLoadHeaderCount.RecId;
        }
        bundleHeaderTmp.BundleReportHeaderGuidStr = bundleHeaderReportGuid;
        bundleHeaderTmp.insert();

        if (procMetrics)
        {
            select count(RecId) from shipmentLoadLines
                where shipmentLoadLines.ShipmentId == shipmentId;

            procMetrics.incLineCount(shipmentLoadLines.RecId);
        }

        if (isReprint || conFind(isReportPrinted, classStr(METSalesDangerousGoodsManifestDP)) == 0)
        {
            if (procMetrics)
            {
                procMetrics.startDescriptionTime(2, "@MET:DangerousGoodsManifest");
            }
            commonReportContract = new METCommonReportContract();
            headerTableGuid = guid2Str(newGuid()) ;
            commonReportContract.parmRecId(shipmentLoadHeader.RecId);

            metSalesDangerousGoodsManifestDP.parmDataContract(commonReportContract);
            metSalesDangerousGoodsManifestDP.setBundlingGuid(bundleHeaderReportGuid, headerTableGuid);
            metSalesDangerousGoodsManifestDP.processReport();

            isReportPrinted += classStr(METSalesDangerousGoodsManifestDP);

            if (procMetrics)
            {
                procMetrics.incDescriptionCount(2);
                procMetrics.endDescriptionTime(2);
            }
        }

        if (isReprint || conFind(isReportPrinted, classStr(METPickupAdviceReportDP)) == 0)
        {
            if (procMetrics)
            {
                procMetrics.startDescriptionTime(3, "@MET:METPickupAdviceReport");
            }

            METSalesOrderShipmentLoadHeader shipmentLoadHeaderLoc;
            //Pickup advice report
            while select shipmentLoadHeaderLoc
                    group by CustAccount
                    where  shipmentLoadHeaderLoc.LoadId == loadId
            {
                this.processsPickupAdvice(shipmentLoadHeaderLoc.CustAccount, loadId);
            }
            if (procMetrics)
            {
                procMetrics.incDescriptionCount(3);
                procMetrics.endDescriptionTime(3);
            }

            isReportPrinted += classStr(METPickupAdviceReportDP);
        }

        if (isReprint || conFind(isReportPrinted, classStr(METCoverNoteDP)) == 0)
        {
            //***** Shipment based report ***//
            if (procMetrics)
            {
                procMetrics.startDescriptionTime(4, "@MET:CoverNote");
            }
            //CoverNote
            coverNoteContract = new METCoverNoteContract();
            headerTableGuid = guid2Str(newGuid());
            coverNoteContract.parmShipmentId(shipmentLoadHeader.ShipmentId);
            coverNoteDP.parmDataContract(coverNoteContract);
            coverNoteDP.setBundlingGuid(bundleHeaderReportGuid, headerTableGuid);
            coverNoteDP.processReport();

            if (procMetrics)
            {
                procMetrics.incDescriptionCount(4);
                procMetrics.endDescriptionTime(4);
            }
            isReportPrinted += classStr(METCoverNoteDP);
        }

        if (isReprint || conFind(isReportPrinted, classStr(METSalesMultimodalDangerousGoodsDP)) == 0)
        {
            if (procMetrics)
            {
                procMetrics.startDescriptionTime(5, "@MET:SODMultimodalDG");
            }

            //Multimodal Dangerous goods
            commonReportContract = new METCommonReportContract();
            headerTableGuid = guid2Str(newGuid()) ;
            commonReportContract.parmRecId(shipmentLoadHeader.RecId);
            salesMultimodalDangerousGoodsDP.parmDataContract(commonReportContract);
            salesMultimodalDangerousGoodsDP.setBundlingGuid(bundleHeaderReportGuid, headerTableGuid);
            salesMultimodalDangerousGoodsDP.processReport();

            isReportPrinted += classStr(METSalesMultimodalDangerousGoodsDP);

            if (procMetrics)
            {
                procMetrics.incDescriptionCount(5);
                procMetrics.endDescriptionTime(5);
            }
        }

        if (isReprint || conFind(isReportPrinted, classStr(METCCRDP)) == 0)
        {
            if (procMetrics)
            {
                procMetrics.startDescriptionTime(6, "@MET:SODConContentReport");
            }

            //Container content report
            commonReportContract = new METCommonReportContract();
            headerTableGuid = guid2Str(newGuid()) ;
            commonReportContract.parmRecId(shipmentLoadHeader.RecId);
            ccrDP.parmDataContract(commonReportContract);
            ccrDP.setBundlingGuid(bundleHeaderReportGuid, headerTableGuid);
            ccrDP.processReport();

            isReportPrinted += classStr(METCCRDP);

            if (procMetrics)
            {
                procMetrics.incDescriptionCount(6);
                procMetrics.endDescriptionTime(6);
            }
        }

        CustInvoiceJour custInvoiceJour;

        select firstonly RecId from custInvoiceJour
                where custInvoiceJour.METShipmentId == shipmentId;

        CustPackingSlipJour custPackingSlipJour;

        select firstonly RecId from custPackingSlipJour
            where custPackingSlipJour.METShipmentId == shipmentId;

        if (finalisationDocument != METFinalizationDocument::None || (shipmentLoadHeader.PendingDocument && custPackingSlipJour.RecId))
        {
            if (procMetrics)
            {
                procMetrics.startDescriptionTime(7, "@ExtendedItallianLocalization:DeliveryNote");
            }

            //Delivery note
            deliveryNoteContract = new METDeliveryNoteReportContract();
            headerTableGuid = guid2Str(newGuid()) ;
            deliveryNoteContract.parmShipmentID(shipmentLoadHeader.ShipmentId);

            deliveryNoteReportDP.parmDataContract(deliveryNoteContract);
            deliveryNoteReportDP.setBundlingGuid(bundleHeaderReportGuid, headerTableGuid);
            deliveryNoteReportDP.processReport();

            isdeliveryNotePrinted = true;

            if (procMetrics)
            {
                procMetrics.incDescriptionCount(7);
                procMetrics.endDescriptionTime(7);
            }
        }

        if (finalisationDocument == METFinalizationDocument::Invoice || (shipmentLoadHeader.PendingDocument && custInvoiceJour.RecId))
        {
            if (procMetrics)
            {
                procMetrics.startDescriptionTime(8, "@CostAccountingService:DocumentType_SalesInvoice");
            }

            if (!WHSParameters::find().METEnableLegacyInvoicePrinting)
            {
                METSalesInvoiceDataGenerator dataGenerator = METSalesInvoiceDataGenerator::construct(shipmentId, bundleHeaderReportGuid);
                dataGenerator.generateSalesInvoiceData(bundleSalesInvoiceHeaderFooterTmp, bundleSalesInvoiceTmp, bundleSalesCTInvoiceTmp);
            }
            else
            {
                //Sales Invoice
                this.generateSalesInvoiceReport(shipmentId, bundleHeaderReportGuid);
            }

            isInvoicePrinted = true;

            if (procMetrics)
            {
                procMetrics.incDescriptionCount(8);
                procMetrics.endDescriptionTime(8);
            }
        }

        if (isReprint || conFind(isReportPrinted, classStr(METSOContinuingPermissionNoticeDP)) == 0)
        {
            if (procMetrics)
            {
                procMetrics.startDescriptionTime(9, "@MET:METPermissionNoticeContract");
            }
            while select shipmentLoadLines
                group by OrderNum
                where shipmentLoadLines.ShipmentId == shipmentId
            {
                //Continue permission notice contract
                continuePermissionNoticeContract = new METCommonContinuingPermissionNoticeContract();
                headerTableGuid = guid2Str(newGuid());
                continuePermissionNoticeContract.parmSalesId(shipmentLoadLines.OrderNum);
                soContinuingPermissionNoticeDP.parmDataContract(continuePermissionNoticeContract);
                soContinuingPermissionNoticeDP.setBundlingGuid(bundleHeaderReportGuid, headerTableGuid);
                soContinuingPermissionNoticeDP.processReport();

                isReportPrinted += classStr(METSOContinuingPermissionNoticeDP);

                if (procMetrics)
                {
                    procMetrics.incDescriptionCount(9);
                }
            }

            if (procMetrics)
            {
                procMetrics.endDescriptionTime(9);
            }
        }

        METSalesOrderShipmentLoadHeader shipmentLoadHeaderUpdate = METSalesOrderShipmentLoadHeader::findByRecId(shipmentLoadHeader.RecId, true);

        ttsbegin;

        shipmentLoadHeaderUpdate.DocumentPrintedCon = isReportPrinted;
        if (shipmentLoadHeaderUpdate.PendingDocument && isdeliveryNotePrinted && isInvoicePrinted)
        {
            shipmentLoadHeaderUpdate.PendingDocument = NoYes::No;
            shipmentLoadHeaderUpdate.update();
        }
        shipmentLoadHeaderUpdate.update();
        ttscommit;

    }
    catch
    {
        throw Error(strFmt("@MET:BundlingError", shipmentId));
    }
}

/// <summary>
/// This method will process pickup advice agaisnt each RMA number
/// </summary>
/// <param name = "_custAccount">CustAccount</param>
/// <param name = "_loadId">LoadId</param>
private void processsPickupAdvice(CustAccount   _custAccount, MetLoadId _loadId)
{
    SalesTable                          salesTable;
    METSalesTable                       metSalesTable;
    METSalesTable                       metSalesTableLoc;
    SalesLine                           salesLine;
    METCustParameters                   metCustParameters;

    select firstonly DispositionCodeRegistration from metCustParameters;

    while select ReturnItemNum, RecId, SalesId from salesTable
        where salesTable.CustAccount == _custAccount
            && salesTable.SalesType == SalesType::ReturnItem &&
            (salesTable.ReturnStatus == ReturnStatusHeader::Open ||
            salesTable.ReturnStatus == ReturnStatusHeader::Created)
        exists join metSalesTable
            where metSalesTable.SalesTable == salesTable.RecId &&
                metSalesTable.PickupAdviceLoadIdPrint == _loadId
    {
        select firstonly RecId from salesLine
            where salesLine.SalesId == salesTable.SalesId
               && salesLine.ReturnDispositionCodeId == metCustParameters.DispositionCodeRegistration;

        if (salesLine.RecId)
        {
            ttsbegin;
            pickupAdviceReportContract = new METPickupAdviceReportContract();
            headerTableGuid = guid2Str(newGuid());

            pickupAdviceReportContract.parmRMANumber(salesTable.ReturnItemNum);
            pickupAdviceReportDP.parmDataContract(pickupAdviceReportContract);
            pickupAdviceReportDP.setBundlingGuid(bundleHeaderReportGuid, headerTableGuid);
            pickupAdviceReportDP.processReport();

            ttscommit;
        }
    }
}

private void generateSalesInvoiceReport(METShipmentId  _shipmentId, Str1260  _bundleHeaderReportGuid)
{
    SalesInvoiceTmp         salesInvoicetmp;
    CustInvoiceJour         custInvoiceJour;
    int64                   transactionIdForCurrentSession;

    uc.ttsbegin();

    ttsbegin;
    while select custInvoiceJour where custInvoiceJour.METShipmentId == _shipmentId
    {
        SalesInvoiceContract salesInvoiceContract = new SalesInvoiceContract();

        salesInvoiceContract.parmRecordId(custInvoiceJour.RecId);

        salesInvoiceContract.parmSuppressDepreciationOfPaymentSection(true);

        SalesInvoiceDP salesinvoicedp = new SalesInvoiceDP();
        //salesinvoicedp.parmCreatedTransactionId(transactionIdForCurrentSession);
        salesinvoicedp.parmDataContract(salesInvoiceContract);
        salesinvoicedp.parmUserConnection(uc);
        salesinvoicedp.processReport();
        transactionIdForCurrentSession = appl.curTransactionId();

        this.insertSalesInvoiceBundleDetails(transactionIdForCurrentSession, _bundleHeaderReportGuid, salesinvoicedp);

    }
    ttscommit;
    uc.ttscommit();
}

private void insertSalesInvoiceBundleDetails(createdTransactionId _transactionId, Str1260   _bundleHeaderReportGuid, SalesinvoiceDP _salesInvoiceDp)
{
    METSalesCTInvoiceTmp            metSalesCTInvoiceTmp = _salesInvoiceDp.getMETSalesCTInvoiceTmp();
    SalesInvoiceHeaderFooterTmp     salesInvoiceHeaderFooterTmp = _salesInvoiceDp.getSalesInvoiceHeaderFooterTmp();
    SalesInvoiceLocalizationTmp     salesInvoiceLocalizationTmp = _salesInvoiceDp.getSalesInvoiceLocalizationTmp();

    SalesInvoiceTmp                 salesInvoiceTmp;
    SysDocuBrandDetailsRegular      sysDocuBrandDetailsRegular = _salesInvoiceDp.getSysDocuBrandDetailsRegular();
    SalesInvoicePaymentStubTmp      salesInvoicePaymentStubTmp = _salesInvoiceDp.getSalesInvoicePaymentStubTmp();

    METSalesInvoiceDPContext instance = METSalesInvoiceDPContext::current();
    if (!instance)
    {
        salesInvoiceTmp = _salesInvoiceDp.getSalesInvoiceTmp();
    }

    RecordInsertList                bundleSalesCTInvoiceList = new RecordInsertList(tableNum(METBundleSalesCTInvoiceTmp), true, true, true, true, true, bundleSalesCTInvoiceTmp);
    RecordInsertList                bundleSalesInvoiceHeaderFooterList = new RecordInsertList(tableNum(METBundleSalesInvoiceHeaderFooterTmp), true, true, true, true, true, bundleSalesInvoiceHeaderFooterTmp);
    RecordInsertList                bundleSalesInvoiceLocalizationList = new RecordInsertList(tableNum(METBundleSalesInvoiceLocalizationTmp), true, true, true, true, true, bundleSalesInvoiceLocalizationTmp);
    RecordInsertList                bundleSalesInvoiceList = new RecordInsertList(tableNum(METBundleSalesInvoiceTmp), true, true, true, true, true, bundleSalesInvoiceTmp);
    RecordInsertList                bundleSysDocuBrandDetailsRegularList = new RecordInsertList(tableNum(METBundleSysDocuBrandDetailsRegularTmp), true, true, true, true, true, bundleSysDocuBrandDetailsRegularTmp);
    RecordInsertList                BundleSalesInvoicePaymentList = new RecordInsertList(tableNum(METBundleSalesInvoicePaymentStubTmp), true, true, true, true, true, bundleSalesInvoicePaymentStubTmp);

    headerTableGuid = guid2Str(newGuid());

    while select forupdate metSalesCTInvoiceTmp where metSalesCTInvoiceTmp.CreatedTransactionId == _transactionId
    {
        bundleSalesCTInvoiceTmp.clear();

        METtablebufTobuf(metSalesCTInvoiceTmp, bundleSalesCTInvoiceTmp);

        bundleSalesCTInvoiceTmp.BundleReportHeaderGuidStr = _bundleHeaderReportGuid;
        bundleSalesCTInvoiceTmp.SalesInvoiceHeaderGuidStr = headerTableGuid;

        bundleSalesCTInvoiceList.add(bundleSalesCTInvoiceTmp);
        metSalesCTInvoiceTmp.delete();
    }
    bundleSalesCTInvoiceList.insertDatabase();

    while select forupdate salesInvoiceHeaderFooterTmp where salesInvoiceHeaderFooterTmp.CreatedTransactionId == _transactionId
    {
        bundleSalesInvoiceHeaderFooterTmp.clear();

        METtablebufTobuf(salesInvoiceHeaderFooterTmp, bundleSalesInvoiceHeaderFooterTmp);

        bundleSalesInvoiceHeaderFooterTmp.BundleReportHeaderGuidStr = _bundleHeaderReportGuid;
        bundleSalesInvoiceHeaderFooterTmp.SalesInvoiceHeaderGuidStr = headerTableGuid;

        bundleSalesInvoiceHeaderFooterList.add(bundleSalesInvoiceHeaderFooterTmp);
        salesInvoiceHeaderFooterTmp.delete();
    }
    bundleSalesInvoiceHeaderFooterList.insertDatabase();

    while select forupdate salesInvoiceLocalizationTmp where salesInvoiceLocalizationTmp.CreatedTransactionId == _transactionId
    {
        bundleSalesInvoiceLocalizationTmp.clear();

        METtablebufTobuf(salesInvoiceLocalizationTmp, bundleSalesInvoiceLocalizationTmp);

        bundleSalesInvoiceLocalizationTmp.BundleReportHeaderGuidStr = _bundleHeaderReportGuid;
        bundleSalesInvoiceLocalizationTmp.SalesInvoiceHeaderGuidStr = headerTableGuid;

        bundleSalesInvoiceLocalizationList.add(bundleSalesInvoiceLocalizationTmp);
        salesInvoiceLocalizationTmp.delete();
    }
    bundleSalesInvoiceLocalizationList.insertDatabase();

    while select forupdate salesInvoiceTmp where salesInvoiceTmp.CreatedTransactionId == _transactionId
    {
        bundleSalesInvoiceTmp.clear();

        METtablebufTobuf(salesInvoiceTmp, bundleSalesInvoiceTmp);

        bundleSalesInvoiceTmp.BundleReportHeaderGuidStr = _bundleHeaderReportGuid;
        bundleSalesInvoiceTmp.SalesInvoiceHeaderGuidStr = headerTableGuid;

        bundleSalesInvoiceList.add(bundleSalesInvoiceTmp);
        salesInvoiceTmp.delete();
    }
    bundleSalesInvoiceList.insertDatabase();

    while select forupdate sysDocuBrandDetailsRegular where sysDocuBrandDetailsRegular.CreatedTransactionId == _transactionId
    {
        bundleSysDocuBrandDetailsRegularTmp.clear();

        METtablebufTobuf(sysDocuBrandDetailsRegular, bundleSysDocuBrandDetailsRegularTmp);

        bundleSysDocuBrandDetailsRegularTmp.BundleReportHeaderGuidStr = _bundleHeaderReportGuid;
        bundleSysDocuBrandDetailsRegularTmp.SalesInvoiceHeaderGuidStr = headerTableGuid;

        bundleSysDocuBrandDetailsRegularList.add(bundleSysDocuBrandDetailsRegularTmp);
        sysDocuBrandDetailsRegular.delete();
    }
    bundleSysDocuBrandDetailsRegularList.insertDatabase();

    if (instance)
    {
        instance.dispose();
    }
}

